function Thumb({ image, label, large = false }: { image: AdminHeritage["image"]; label: string; large?: boolean }) { return <Photo src={image?.thumbnail_url || image?.url} alt={image?.alt_text || label} className={`${large ? "h-[76px] w-24" : "h-11 w-14"} shrink-0 rounded-lg object-cover`} />; }
function Meta({ label, value, href }: { label: string; value: string | null | undefined; href?: string | null }) { return <div className="grid grid-cols-[72px_minmax(0,1fr)] gap-2"><dt className="text-parchment/35">{label}</dt><dd className="min-w-0 truncate text-parchment/65">{value ? href ? <a href={href} target="_blank" rel="noreferrer" className="text-gold-bright">{value}</a> : value : "Not recorded"}</dd></div>; }
function Pagination({ pagination, currentPage, pageCount, page }: { pagination: { total: number; limit: number; offset: number }; currentPage: number; pageCount: number; page: (offset: number) => void }) { if (pagination.total <= pagination.limit) return null; const to = Math.min(pagination.offset + pagination.limit, pagination.total); return <nav aria-label="Pagination" className="mt-5 flex flex-wrap items-center justify-between gap-3"><p className="text-xs text-parchment/40">Showing {(pagination.offset + 1).toLocaleString()}–{to.toLocaleString()} of {pagination.total.toLocaleString()}</p><div className="flex items-center gap-2"><button type="button" disabled={currentPage <= 1} onClick={() => page(pagination.offset - pagination.limit)} className={secondary}><ChevronLeft className="h-4 w-4" />Previous</button><span className="px-2 text-xs text-parchment/55">Page {currentPage} of {pageCount}</span><button type="button" disabled={currentPage >= pageCount} onClick={() => page(pagination.offset + pagination.limit)} className={secondary}>Next<ChevronRight className="h-4 w-4" /></button></div></nav>; }
function Empty({ title, body }: { title: string; body: string }) { return <div className="grid min-h-56 place-items-center rounded-2xl border border-white/[0.09] bg-[#15120f] px-6 py-10 text-center sm:col-span-2 2xl:col-span-3"><div><ImageIcon className="mx-auto h-8 w-8 text-gold/60" /><h2 className="font-display mt-3 text-2xl">{title}</h2><p className="mt-2 max-w-lg text-sm leading-6 text-parchment/45">{body}</p></div></div>; }

function CategoryAdmin({ categories, reload, report, fail }: { categories: HeritageCategory[]; reload: () => Promise<void>; report: (text: string) => void; fail: (text: string) => void }) {
  const [editing, setEditing] = useState<HeritageCategory | null>(null); const [name, setName] = useState(""); const [slug, setSlug] = useState(""); const [saving, setSaving] = useState(false); const [candidate, setCandidate] = useState<number | null>(null); const [deleting, setDeleting] = useState<number | null>(null);
  const reset = () => { setEditing(null); setName(""); setSlug(""); };
  const save = async (event: FormEvent) => { event.preventDefault(); if (saving) return; setSaving(true); try { if (editing) await updateAdminCategory(editing.id, { name, slug }); else await createAdminCategory({ name, slug }); report(editing ? "Category updated." : "Category created."); reset(); await reload(); } catch (reason) { fail(reason instanceof Error ? reason.message : "Could not save category."); } finally { setSaving(false); } };
  const remove = async (id: number) => { if (deleting !== null) return; setDeleting(id); try { await deleteAdminCategory(id); report("Unused category deleted."); setCandidate(null); await reload(); } catch (reason) { fail(reason instanceof Error ? reason.message : "Could not delete category."); } finally { setDeleting(null); } };
  return <div className="grid gap-5 xl:grid-cols-[minmax(0,0.8fr)_minmax(0,1.2fr)]"><section className="h-fit rounded-2xl border border-white/[0.09] bg-[#15120f] p-5 sm:p-6"><p className="text-[10px] uppercase tracking-[0.22em] text-gold">Taxonomy</p><h2 className="font-display mt-2 text-3xl">{editing ? "Edit category." : "Add a category."}</h2><p className="mt-2 text-sm leading-6 text-parchment/45">Categories remain linked to existing places. A used category cannot be deleted.</p><form onSubmit={save} className="mt-5 grid gap-4"><label className="text-xs text-parchment/55">Category name<input required maxLength={100} value={name} onChange={(e) => setName(e.target.value)} className={inputClass} /></label><label className="text-xs text-parchment/55">URL slug<input required maxLength={100} pattern="[a-z0-9]+(-[a-z0-9]+)*" value={slug} onChange={(e) => setSlug(e.target.value)} className={inputClass} /></label><div className="flex gap-2"><button disabled={saving} className={primary}><Plus className="h-4 w-4" />{saving ? "Saving…" : editing ? "Save category" : "Add category"}</button>{editing ? <button type="button" disabled={saving} onClick={reset} className={secondary}>Cancel edit</button> : null}</div></form></section>
  <section className="overflow-hidden rounded-2xl border border-white/[0.09] bg-[#15120f]"><div className="border-b border-white/[0.07] p-5"><p className="text-[10px] uppercase tracking-[0.2em] text-gold">Current taxonomy</p><h2 className="font-display mt-1 text-2xl">{categories.length} categories</h2></div><div className="divide-y divide-white/[0.06]">{categories.map((category) => <div key={category.id} className="flex flex-wrap items-center justify-between gap-3 px-5 py-4"><div><p className="text-sm font-medium">{category.name}</p><p className="mt-1 text-xs text-parchment/35">/{category.slug}</p></div><div className="flex flex-wrap items-center gap-2"><button type="button" disabled={saving || deleting !== null} onClick={() => { setEditing(category); setName(category.name); setSlug(category.slug); setCandidate(null); }} className={secondary}><Pencil className="h-3.5 w-3.5" />Edit</button>{candidate === category.id ? <><span className="text-xs text-parchment/50">Delete if unused?</span><button type="button" disabled={deleting !== null} onClick={() => void remove(category.id)} className="rounded-lg bg-red-400/10 px-3 py-2 text-xs text-red-100">{deleting === category.id ? "Deleting…" : "Confirm"}</button><button type="button" disabled={deleting !== null} onClick={() => setCandidate(null)} className={secondary}>Cancel</button></> : <button type="button" disabled={saving || deleting !== null} onClick={() => setCandidate(category.id)} className={`${secondary} text-parchment/55`}>Delete if unused</button>}</div></div>)}{!categories.length ? <p className="p-6 text-sm text-parchment/40">No categories are available.</p> : null}</div></section></div>;
}

function Editor({ form, categories, isSaving, editing, setForm, save, cancel }: { form: FormState; categories: HeritageCategory[]; isSaving: boolean; editing: number | null; setForm: (form: FormState) => void; save: (event: FormEvent) => void; cancel: () => void }) {
  const set = (key: string, value: string) => setForm({ ...form, [key]: value }); const fields = ["name", "slug", "historical_period", "state", "locality", "district", "address"];
  return <section className="overflow-hidden rounded-2xl border border-white/[0.09] bg-[#15120f]"><div className="flex flex-wrap items-start justify-between gap-3 border-b border-white/[0.07] p-5 sm:p-6"><div><p className="text-[10px] uppercase tracking-[0.22em] text-gold">Record editor · {editing ? `#${editing}` : "New place"}</p><h2 className="font-display mt-2 text-3xl">{editing ? "Edit heritage place." : "Create heritage place."}</h2><p className="mt-1 text-xs text-parchment/40">Existing identifiers and relationships are preserved when editing.</p></div><button type="button" onClick={cancel} className={secondary}><X className="h-4 w-4" />Close editor</button></div><form onSubmit={save} className="p-5 sm:p-6"><div className="grid gap-4 sm:grid-cols-2 xl:grid-cols-3">{fields.map((key) => <label key={key} className="text-xs capitalize text-parchment/55">{key.replaceAll("_", " ")}<input name={key} required={!['district','locality','address'].includes(key)} value={form[key]} onChange={(e) => set(key, e.target.value)} className={inputClass} /></label>)}
  <label className="text-xs text-parchment/55">Category<select required value={form.category_id} onChange={(e) => set("category_id", e.target.value)} className={inputClass}><option value="">Select category</option>{categories.map((c) => <option key={c.id} value={c.id}>{c.name}</option>)}</select></label><label className="text-xs text-parchment/55">Publication status<select value={form.publication_status} onChange={(e) => set("publication_status", e.target.value)} className={inputClass}><option value="draft">Draft</option><option value="published">Published</option></select></label><label className="text-xs text-parchment/55">Latitude<input type="number" step="any" min="-90" max="90" required={Boolean(form.longitude)} value={form.latitude} onChange={(e) => set("latitude", e.target.value)} className={inputClass} /></label><label className="text-xs text-parchment/55">Longitude<input type="number" step="any" min="-180" max="180" required={Boolean(form.latitude)} value={form.longitude} onChange={(e) => set("longitude", e.target.value)} className={inputClass} /></label><p className="rounded-xl border border-gold/15 bg-gold/[0.035] p-3 text-xs leading-5 text-parchment/50 sm:col-span-2 xl:col-span-3">Changing or adding coordinates requires an HTTPS source supporting this place and human review confidence of at least 0.95. Leave verified coordinates unchanged to retain their citation.</p>
  <div className="sm:col-span-2 xl:col-span-3"><p className="text-[10px] uppercase tracking-[0.2em] text-gold">Coordinate source, when changing coordinates</p><div className="mt-2 grid gap-3 sm:grid-cols-2">{["coordinate_source_title", "coordinate_source_publisher", "coordinate_source_url", "coordinate_source_confidence"].map((key) => <label key={key} className="text-xs capitalize text-parchment/55">{key.replace("coordinate_source_", "").replaceAll("_", " ")}<input name={key} type={key.endsWith("url") ? "url" : key.endsWith("confidence") ? "number" : "text"} min={key.endsWith("confidence") ? 0.95 : undefined} max={key.endsWith("confidence") ? 1 : undefined} step={key.endsWith("confidence") ? 0.001 : undefined} value={form[key]} onChange={(e) => set(key, e.target.value)} className={inputClass} /></label>)}</div></div>
  <ImageAttachmentFields form={form} set={set} />
  {["description", "history", "cultural_significance", "architecture"].map((key) => <label key={key} className="text-xs capitalize text-parchment/55 sm:col-span-2 xl:col-span-3">{key.replaceAll("_", " ")}<textarea required rows={key === "description" ? 3 : 4} value={form[key]} onChange={(e) => set(key, e.target.value)} className={`${inputClass} resize-y`} /></label>)}</div><div className="mt-6 flex flex-wrap gap-2"><button disabled={isSaving} className={primary}><CheckCircle2 className="h-4 w-4" />{isSaving ? "Saving record…" : "Save place"}</button><button type="button" disabled={isSaving} onClick={cancel} className={secondary}>Cancel</button></div></form></section>;
}

function ImageAttachmentFields({ form, set }: { form: FormState; set: (key: string, value: string) => void }) {
  const hasImageDetails = Object.entries(form).some(([key, value]) => key.startsWith("image_") && value.trim() !== "");
  const hasImageUrl = Boolean(form.image_url.trim());
  const setUrl = (key: string, label: string, required: boolean) => (
    <label className="text-xs text-parchment/55">{label}{required ? " (required)" : ""}
      <input type="url" name={key} maxLength={2000} pattern="https://.+" required={required} value={form[key]} onChange={(event) => set(key, event.target.value)} className={inputClass} />
    </label>
  );

  return <fieldset className="grid gap-3 rounded-2xl border border-white/[0.09] bg-white/[0.02] p-4 sm:col-span-2 xl:col-span-3 sm:p-5">
    <legend className="px-2 text-[10px] uppercase tracking-[0.2em] text-gold">Attach an image (optional)</legend>
    <p className="text-xs leading-5 text-parchment/50">Use a hosted HTTPS image and its source and license details. New attachments are saved as unverified for review in the Image library; existing images are left untouched.</p>
    <div className="grid gap-3 sm:grid-cols-2 xl:grid-cols-3">
      {setUrl("image_url", "Image URL (HTTPS)", hasImageDetails)}
      {setUrl("image_thumbnail_url", "Thumbnail URL (optional)", false)}
      <label className="text-xs text-parchment/55">Caption (optional)<input name="image_caption" maxLength={1000} value={form.image_caption} onChange={(event) => set("image_caption", event.target.value)} className={inputClass} /></label>
      <label className="text-xs text-parchment/55">Alt text{hasImageUrl ? " (required)" : ""}<input name="image_alt_text" maxLength={500} required={hasImageUrl} value={form.image_alt_text} onChange={(event) => set("image_alt_text", event.target.value)} className={inputClass} /></label>
      <label className="text-xs text-parchment/55">Creator / photographer{hasImageUrl ? " (required)" : ""}<input name="image_creator" maxLength={300} required={hasImageUrl} value={form.image_creator} onChange={(event) => set("image_creator", event.target.value)} className={inputClass} /></label>
      <label className="text-xs text-parchment/55">Credit (optional)<input name="image_credit" maxLength={500} value={form.image_credit} onChange={(event) => set("image_credit", event.target.value)} className={inputClass} /></label>
      <label className="text-xs text-parchment/55">License{hasImageUrl ? " (required)" : ""}<input name="image_license" maxLength={200} required={hasImageUrl} value={form.image_license} onChange={(event) => set("image_license", event.target.value)} className={inputClass} /></label>
      {setUrl("image_license_url", "License terms URL", hasImageUrl)}
      {setUrl("image_source_url", "Source page URL", hasImageUrl)}
      <label className="text-xs text-parchment/55">Documented photo date (optional)<input type="date" name="image_documented_date" value={form.image_documented_date} onChange={(event) => set("image_documented_date", event.target.value)} className={inputClass} /></label>
    </div>
  </fieldset>;
}
